{"code": "from PIL import Image
import os

def check_images(directory):
    problematic_files = []
    for root, dirs, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            try:
                with Image.open(file_path) as img:
                    img.verify()
            except Exception as e:
                problematic_files.append((file_path, str(e)))

    return problematic_files

print("Checking training_set:")
problematic = check_images('data_small/training_set')
for file_path, error in problematic:
    print(f"Problem: {file_path} - {error}")

print("\nChecking test_set:")
problematic = check_images('data_small/test_set')
for file_path, error in problematic:
    print(f"Problem: {file_path} - {error}")"}

